71: <script>
72: import { getToken } from '@/utils/auth.js'
73: import { PROGRESS_NODE_LABELS } from './PresaleBuildingTable.vue'
74: 
75: /**
76:  * 工程形象进度维护（接口文档 §2.8）
77:  * 附件必传：先经通用附件上传 busCode=PRESALE_PROGRESS_FILE、busId=楼幢快照ID，
78:  * 再调 /presale/permit/building/progress。
79:  */
80: export default {
81:   name: 'PresaleProgressDialog',
82:   props: {
83:     visible: {
84:       type: Boolean,
85:       default: false
86:     },
87:     readonly: {
88:       type: Boolean,
89:       default: false
90:     },
91:     presalePermitId: {
92:       type: [String, Number],
93:       default: ''
94:     },
95:     /** 楼幢快照列表（须已保存，含 presalePermitBuildingId） */
96:     buildings: {
97:       type: Array,
98:       default: () => []
99:     },
100:     /** 预选中的楼幢快照ID */
101:     preselectedIds: {
102:       type: Array,
103:       default: () => []
104:     }
105:   },
106:   data() {
107:     return {
108:       loading: false,
109:       saving: false,
110:       form: {
111:         buildingSnapshotIds: [],
112:         progressNode: undefined
113:       },
114:       /** 已上传附件的楼幢快照ID集合（含历史已传） */
115:       uploadedSnapshotIds: [],
116:       rules: {
117:         buildingSnapshotIds: [{ required: true, message: '请选择楼幢', trigger: 'change' }],
118:         progressNode: [{ required: true, message: '请选择形象进度', trigger: 'change' }]
119:       }
120:     }
121:   },
122:   computed: {
123:     dialogVisible: {
124:       get() {
125:         return this.visible
126:       },
127:       set(val) {
128:         this.$emit('update:visible', val)
129:       }
130:     },
131:     uploadFileUrl() {
132:       return import.meta.env.VITE_APP_BASE_API + '/file/appendix/upload'
133:     },
134:     headers() {
135:       return {
136:         Authorization: 'Bearer ' + getToken()
137:       }
138:     },
139:     buildingOptions() {
140:       return this.buildings
141:         .filter((row) => row.presalePermitBuildingId)
142:         .map((row) => ({ dictValue: row.presalePermitBuildingId, dictLabel: row.buildingNo || row.buildingCode || '-' }))
143:     },
144:     selectedSnapshots() {
145:       return this.buildings.filter(
146:         (row) => row.presalePermitBuildingId && this.form.buildingSnapshotIds.includes(row.presalePermitBuildingId)
147:       )
148:     },
149:     currentProgressText() {
150:       const rows = this.selectedSnapshots
151:       if (!rows.length) return ''
152:       const labels = [...new Set(rows.map((row) => (row.progressNode != null ? PROGRESS_NODE_LABELS[row.progressNode] || '-' : '-')))]
153:       return labels.join('、')
154:     },
155:     progressOptions() {
156:       return Object.keys(PROGRESS_NODE_LABELS).map((value) => ({
157:         dictValue: value,
158:         dictLabel: PROGRESS_NODE_LABELS[value]
159:       }))
160:     }
161:   },
162:   methods: {
163:     handleOpen() {
164:       this.form.buildingSnapshotIds = [...(this.preselectedIds || [])]
165:       this.form.progressNode = undefined
166:       this.uploadedSnapshotIds = []
167:       if (this.readonly) {
168:         this.loadExistingAttachments()
169:       }
170:     },
171:     /** 查看模式：按 busId+busCode 查询已挂接附件（不走要件配置） */
172:     loadExistingAttachments() {
173:       const ids = this.buildingOptions.map((item) => item.dictValue)
174:       if (!ids.length) return
175:       this.loading = true
176:       Promise.all(
177:         ids.map((busId) =>
178:           this.$post('/file/appendix/listAppendixPackage', {
179:             busCode: 'PRESALE_PROGRESS_FILE',
180:             busId
181:           })
182:             .then((res) => {
183:               const groups = res.data || []
184:               const hasFiles = groups.some((item) => item.appendices && item.appendices.length)
185:               return { busId, hasFiles }
186:             })
187:             .catch(() => ({ busId, hasFiles: false }))
188:         )
189:       )
190:         .then((results) => {
191:           this.uploadedSnapshotIds = results.filter((item) => item.hasFiles).map((item) => item.busId)
192:         })
193:         .finally(() => {
194:           this.loading = false
195:         })
196:     },
197:     uploadData(snapshot) {
198:       return {
199:         busId: snapshot.presalePermitBuildingId,
200:         busCode: 'PRESALE_PROGRESS_FILE'
201:       }
202:     },
203:     handleBeforeUpload(file) {
204:       if (file.size > 5 * 1024 * 1024) {
205:         this.$message.error('上传文件大小不能超过5MB')
206:         return false
207:       }
208:       return true
209:     },
210:     handleUploadError() {
211:       this.$message.error('上传失败')
212:     },
213:     handleUploadSuccess(res, file, snapshot) {
214:       if (res.code !== 200) {
215:         this.$message.error(res.msg || '上传失败')
216:         return
217:       }
218:       if (!this.uploadedSnapshotIds.includes(snapshot.presalePermitBuildingId)) {
219:         this.uploadedSnapshotIds.push(snapshot.presalePermitBuildingId)
220:       }
221:       this.$message.success(`${snapshot.buildingNo || snapshot.buildingCode || '-'} 形象进度附件上传成功`)
222:     },
223:     hasAttachment(snapshot) {
224:       return this.uploadedSnapshotIds.includes(snapshot.presalePermitBuildingId)
225:     },
226:     handleSave() {
227:       this.$refs.progressForm.validate((valid) => {
228:         if (!valid) return
229:         const missing = this.selectedSnapshots.filter((snapshot) => !this.hasAttachment(snapshot))
230:         if (missing.length) {
231:           this.msgError(`楼幢[${missing.map((row) => row.buildingNo || row.buildingCode || '-').join('、')}]请上传工程形象进度附件`)
232:           return
233:         }
234:         this.saving = true
235:         this.$post('/presale/permit/building/progress', {
236:           presalePermitId: this.presalePermitId,
237:           buildingSnapshotIds: this.form.buildingSnapshotIds,
238:           progressNode: this.form.progressNode
239:         })
240:           .then((res) => {
241:             if (res.code !== 200) {
242:               this.msgError(res.msg || '保存失败')
243:               return
244:             }
245:             this.msgSuccess('形象进度维护成功')
246:             this.$emit('success')
247:             this.dialogVisible = false
248:           })
249:           .finally(() => {
250:             this.saving = false
251:           })
252:       })
253:     }
254:   }
255: }
256: </script>
